/* TWM World Sandbox, автономный UI-компонент v2. Без CDN и без подмены вычислений.
   Полноценный React/Motion-исходник: ui/src/index.tsx (собирается npm run build). */
const instances = new WeakMap();
const enc = s => String(s ?? '').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const clone = o => JSON.parse(JSON.stringify(o));
const icons = {atom:'⚛',box:'⬡',door:'▥',key:'⚿',room:'⌂',graph:'⋈',law:'≋',bolt:'ϟ',clock:'◷',warning:'!',check:'✓',plus:'+',reset:'↺',edit:'✎',arrow:'→',delete:'×'};
const types = {character:['Персонаж','atom','mint'],door:['Дверь','door','amber'],key:['Ключ','key','sky'],room:['Комната','room','violet'],object:['Объект','box','sky']};
const type = kind => types[kind]||types.object;
const name = (s,n=23) => String(s).length > n ? String(s).slice(0,n-1)+'…':String(s);
const choice=(list,value)=>list.map(x=>`<option value="${enc(x)}" ${x===value?'selected':''}>${enc(x)}</option>`).join('');
const fmt=v=>Number.isFinite(v)?Number(v).toFixed(2):'—';
const rusEffect=s=>String(s).replace('resource(','запас(').replace('relation(','связь(').replace(' = add',' — добавить').replace(' = remove',' — удалить');
const eq = s=>`<span class="tag tag-${s==='success'?'mint':s==='warning'?'amber':'neutral'}">${s==='success'?'ВЫБРАНО':s==='warning'?'КОНФЛИКТ':'ВАРИАНТ'}</span>`;
const positions={character:[[19,33],[26,64],[12,78]],door:[[73,36],[82,65],[66,16]],key:[[45,20],[39,55],[61,55]],room:[[52,76],[78,78],[29,83]],object:[[42,41],[61,43],[16,53]]};
function posFor(entities){const counters={};const m={};entities.forEach((e,i)=>{const k=e.kind||'object',n=counters[k]||0;counters[k]=n+1;m[e.id]=(positions[k]||positions.object)[n]||[15+(i*19)%72,20+(i*31)%65];});return m;}
function expr(r){if(!r)return '—';if('table'in r)return '('+expr(r.left)+' ['+(r.table||[]).join('')+'] '+expr(r.right)+')';return `${r.required===false?'НЕ ':''}${r.predicate}(${r.left}, ${r.right})`}
function current(c){const n=c.selectedHistory;if(n===null)return {world:c.world,before:c.data.history.at(-1)?.world_state_before,record:c.data.history.at(-1)};if(n===0)return {world:c.data.history[0]?.world_state_before||c.data.world_state,before:null,record:null};const r=c.data.history[n-1];return {world:r?.world_state_after||c.world,before:r?.world_state_before,record:r};}
function worldGraph(c,world,before){
 const map=posFor(world.entities);const earlier=new Set((before?.relations||world.relations).map(r=>[r.predicate,r.source,r.target].join('/')));
 const added=world.relations.filter(r=>!earlier.has([r.predicate,r.source,r.target].join('/')));
 const changed=new Set(world.entities.filter(e=>before&&e.stock!==before.entities.find(x=>x.id===e.id)?.stock).map(e=>e.id));
 const unlocked=new Set(world.relations.filter(r=>r.predicate.includes('отперто')||r.predicate.includes('открыто')).map(r=>r.target));
 const edges=world.relations.map((r,i)=>{const a=map[r.source],b=map[r.target];if(!a||!b)return '';const fresh=added.includes(r);return `<path d="M ${a[0]} ${a[1]} Q ${(a[0]+b[0])/2} ${Math.min(a[1],b[1])-7} ${b[0]} ${b[1]}" stroke="${fresh?'#69efbc':'#4e8390'}" stroke-width="${fresh?.35:.18}" stroke-dasharray="${fresh?'':'1.3 1'}" fill="none"/>`}).join('');
 const labels=world.relations.map(r=>{const a=map[r.source],b=map[r.target];return !a||!b?'':`<span class="edge-label" title="${enc(r.predicate)}(${enc(r.source)},${enc(r.target)})" style="left:${(a[0]+b[0])/2}%;top:${(a[1]+b[1])/2-6}%">${enc(name(r.predicate,17))}</span>`}).join('');
 const nodes=world.entities.map(e=>{const [x,y]=map[e.id],info=type(e.kind),t=info[1];return `<button class="arena-node ${changed.has(e.id)?'is-changed':''} ${unlocked.has(e.id)?'is-unlocked':''} ${c.selectedEntity===e.id?'is-selected':''}" data-act="entity" data-id="${enc(e.id)}" style="left:${x}%;top:${y}%;animation:node-pop .5s both"><span class="node-accent"></span><span class="node-inner"><span class="object-icon ${info[2]}">${icons[t]}</span><span class="node-names"><b>${enc(name(e.id,20))}</b><small>${info[0]}</small></span>${unlocked.has(e.id)?'<span class="node-unlocked">✓</span>':''}</span><span class="node-bottom"><span>РЕСУРС ${e.stock} <i>/ ${e.capacity}</i></span>${changed.has(e.id)?'<span class="node-delta">ϟ Δ</span>':''}</span></button>`}).join('');
 return `<div class="arena"><div class="arena-grid"></div><div class="arena-vignette"></div><div class="arena-top-left"><span class="micro-box">◉ ТОПОГРАФИЯ / ГРАФ ОТНОШЕНИЙ</span><div class="arena-sub">${world.entities.length} объектов · ${world.relations.length} связей</div></div><div class="arena-top-right"><span class="tag tag-${c.selectedHistory!==null?'amber':'mint'}">${c.selectedHistory!==null?'ПРОСМОТР ИСТОРИИ':'ТЕКУЩЕЕ СОСТОЯНИЕ'}</span></div><svg class="links-canvas" viewBox="0 0 100 100" preserveAspectRatio="none">${edges}</svg>${labels}${nodes}<div class="arena-bottom-left"><div class="legend"><span><i class="legend-circle mint"></i> Сущности</span><span><i class="legend-line"></i> Отношения</span><span><i class="legend-circle changed"></i> Изменения</span></div></div><div class="arena-bottom-right"><div class="coord">ПРОЕКЦИЯ: СХЕМА ФАКТОВ<br/>НЕ ГЕОМЕТРИЧЕСКАЯ ФИЗИКА</div></div></div>`;
}
function entityInspector(c){const w=c.world;return `<section class="panel-section"><div class="section-title"><span>⬡ СУЩНОСТИ <small>${w.entities.length}</small></span><button class="btn btn-ghost" data-act="add-entity" title="Добавить объект">+</button></div><div class="entity-list">${w.entities.map(e=>{const info=type(e.kind),open=c.selectedEntity===e.id;return `<div class="entity ${open?'selected':''}"><button class="entity-head" data-act="entity" data-id="${enc(e.id)}"><span class="object-icon ${info[2]}">${icons[info[1]]}</span><span class="entity-ident"><b>${enc(name(e.id))}</b><small>${info[0]}</small></span><span class="mini-value ${e.stock<0||e.stock>e.capacity?'danger-text':''}">${e.stock}<span>/${e.capacity}</span></span>⌄</button><div class="resource-track"><span style="width:${Math.max(0,Math.min(100,100*e.stock/(e.capacity||1)))}%"></span></div>${open?`<div class="entity-detail"><label>Запас <input type="number" data-field="stock" data-id="${enc(e.id)}" value="${e.stock}"></label><label>Вместимость <input type="number" data-field="capacity" data-id="${enc(e.id)}" value="${e.capacity}"></label><button class="text-danger" data-act="del-entity" data-id="${enc(e.id)}" ${w.entities.length<=3?'disabled':''}>× Удалить объект</button></div>`:''}</div>`}).join('')}</div>${c.addEntity?`<div class="add-form"><input data-field="new-id" value="${enc(c.newId)}" placeholder="Имя объекта"><select data-field="new-kind">${choice(Object.keys(types),c.newKind)}</select><button class="btn btn-accent" data-act="confirm-entity">Добавить</button></div>`:''}</section>`}
function relationInspector(c){const w=c.world;return `<section class="panel-section"><div class="section-title"><span>⋈ ОТНОШЕНИЯ <small>${w.relations.length}</small></span><button class="btn btn-ghost" data-act="add-relation" title="Добавить отношение">+</button></div><div class="relation-list">${w.relations.length===0?'<p class="micro-muted">В мире нет отношений</p>':''}${w.relations.map((r,i)=>`<div class="relation-row"><span class="relation-pred" title="${enc(r.predicate)}">${enc(name(r.predicate,19))}</span><span class="relation-flow"><b>${enc(name(r.source,12))}</b> → <b>${enc(name(r.target,12))}</b></span><button data-act="del-relation" data-index="${i}" title="Удалить связь">×</button></div>`).join('')}</div>${c.addRelation?`<div class="add-form"><input data-field="rel-p" value="${enc(c.newRelation.predicate)}" placeholder="Предикат"><div class="form-two"><select data-field="rel-a">${choice(w.entities.map(e=>e.id),c.newRelation.source)}</select><select data-field="rel-b">${choice(w.entities.map(e=>e.id),c.newRelation.target)}</select></div><button class="btn btn-accent" data-act="confirm-relation">Добавить факт</button></div>`:''}</section>`}
function lawsInspector(c){return `<section class="panel-section"><div class="section-title"><span>≋ ЗАКОНЫ МИРА <small>${c.laws.filter(l=>l.enabled).length} активны</small></span><button class="btn btn-ghost" data-act="add-law" title="Копировать закон" ${c.laws.length>=5?'disabled':''}>+</button></div><p class="micro-muted intro">Приоритеты входят в признаки нейросети, но не исполняются программно.</p><div class="laws-list">${c.laws.map((l,i)=>`<div class="law ${l.enabled?'':'dimmed'}"><div class="law-top"><span class="law-index">${String(i+1).padStart(2,'0')}</span><span class="law-name">${enc(name(l.id.replaceAll('_',' '),22))}</span><button class="switch ${l.enabled?'active':''}" data-act="toggle-law" data-index="${i}" role="switch" aria-checked="${l.enabled}"><span></span></button></div><p class="law-brief">${{consume:'Расход',produce:'Пополнение',transfer:'Перенос'}[l.mode]||l.mode} ${l.amount} · ${l.relation_add?'добавить':'удалить'} «${enc(name(l.effect_predicate,16))}»</p><div class="law-actions"><span class="tag tag-neutral">приоритет ${l.priority}</span><span class="law-tools"><button data-act="move-law-up" data-index="${i}" ${!i?'disabled':''} title="Выше">↑</button><button data-act="move-law-down" data-index="${i}" ${i===c.laws.length-1?'disabled':''} title="Ниже">↓</button><button data-act="edit-law" data-index="${i}" title="Редактор закона">✎</button><button data-act="del-law" data-index="${i}" ${c.laws.length<=1?'disabled':''} title="Удалить закон">×</button></span></div>${c.editLaw===i?`<div class="law-expanded"><div class="form-two"><label>Режим<select data-law="${i}" data-law-field="mode">${choice(['consume','produce','transfer'],l.mode)}</select></label><label>Количество<input type="number" min="1" data-law="${i}" data-law-field="amount" value="${l.amount}"></label></div><label>Предикат<input data-law="${i}" data-law-field="effect_predicate" value="${enc(l.effect_predicate)}"></label><label>Связь<select data-law="${i}" data-law-field="relation_add"><option value="true" ${l.relation_add?'selected':''}>Добавить</option><option value="false" ${!l.relation_add?'selected':''}>Удалить</option></select></label><label>Условие (JSON AST)<textarea spellcheck="false" rows="7" data-field="condition">${enc(c.conditionDraft)}</textarea></label><p class="micro-muted">${enc(expr(l.condition)).slice(0,210)}</p><button class="btn btn-accent" data-act="save-condition">Применить условие</button></div>`:''}</div>`).join('')}</div></section>`}
function actionConsole(c){const ids=c.world.entities.map(e=>e.id),a=c.action;return `<section class="action-console"><div class="console-top"><span class="console-live"><span></span> ПУЛЬТ ДЕЙСТВИЙ</span><span style="color:#5addb3">ϟ</span></div><div class="action-grid"><label>Кто действует<select data-action="actor">${choice(ids,a.actor)}</select></label><label>Что делает<input data-action="verb" value="${enc(a.verb)}"></label><label>Цель<select data-action="target">${choice(ids,a.target)}</select></label><label>Инструмент<select data-action="instrument"><option value="">Без инструмента</option>${choice(ids,a.instrument||'')}</select></label></div><button class="btn btn-primary run-button" data-act="step" ${c.busy||c.selectedHistory!==null?'disabled':''}>${c.busy?'◌ Модель вычисляет энергии…':'▶ ЗАПУСТИТЬ ДЕЙСТВИЕ →'}</button><div class="console-foot">♢ Только нейронный выбор · без скрытого эталона</div></section>`}
function results(c,record){if(!record)return `<div class="empty-result"><div class="empty-glow">♧</div><h3>Мир готов к эксперименту</h3><p>Меняйте исходные факты и законы, выбирайте действие и запускайте реальную нейросеть TWM v7.10.</p><div class="empty-chain"><span>МИР</span> → <span>ЗАКОНЫ</span> → <span>НЕЙРОСЕТЬ</span> → <span>БУДУЩЕЕ</span></div></div>`;const log=record.response.step_log,w=log.evaluated_subsets.find(x=>x.is_winner);return `<div class="run-summary"><span class="eyebrow">✦ РЕЗУЛЬТАТ НЕЙРОННОГО ПЕРЕХОДА</span><div class="summary-row"><div><h3>${enc(record.action.verb)}<span>(${enc(record.action.actor)}, ${enc(record.action.target)})</span></h3><div class="summary-muted">Победил вариант №${log.winner_subset_id} из ${log.evaluated_subsets.length}</div></div><span class="summary-energy">E = ${w?fmt(w.total_consistency_energy):'—'}</span></div><div class="effect-chips">${w?.effects_applied.length?w.effects_applied.map(t=>`<span>✓ ${enc(rusEffect(t))}</span>`).join(''):'<span>Эффекты не выбраны</span>'}</div>${w?.conflict_detected?'<div class="summary-warning">! Выбран конфликтный исход, результат не исправлен.</div>':''}</div>`}
function multiverse(c,record){if(!record)return `<div class="multiverse-placeholder"><div class="placeholder-orbits">⋈</div><span class="eyebrow">МУЛЬТИВСЕЛЕННАЯ</span><h3>Варианты ещё<br>не вычислены</h3><p>Здесь появятся все подмножества эффектов с настоящими энергиями JointConsistencyEnergy.</p><div class="placeholder-equation">E(S) = E(v7.9) + ΔE(joint)</div></div>`;
 const subsets=record.response.step_log.evaluated_subsets,winner=subsets.find(s=>s.is_winner),sorted=[...subsets].sort((a,b)=>b.total_consistency_energy-a.total_consistency_energy),mini=Math.min(...subsets.map(s=>s.total_consistency_energy)),maxi=Math.max(...subsets.map(s=>s.total_consistency_energy)),shown=c.showAll?sorted:sorted.slice(0,6);
 return `<div class="multiverse"><div class="block-header"><div><span class="eyebrow">⋈ ПРОСТРАНСТВО ВАРИАНТОВ</span><h3>Мультивселенная <span>исходов</span></h3></div><span class="tag tag-mint">${subsets.length} сценариев</span></div><div class="score-method">ϟ <span>JointConsistencyEnergy<br><small>Основа v7.9 + совместная поправка v7.10</small></span></div><div class="winner-hero"><div class="winner-ring">✓</div><div><div class="winner-label">ВЫБРАН МОДЕЛЬЮ · ARGMAX</div><b>Сценарий №${winner?.subset_id??'—'}</b></div><span class="winner-score">${winner?fmt(winner.total_consistency_energy):'—'}</span></div><div class="multiverse-list">${shown.map((s,i)=>{const pct=Math.max(8,(s.total_consistency_energy-mini)/(maxi-mini||1)*92+8);return `<button class="universe-card ${s.is_winner?'victor':''} ${c.selectedSubset===s.subset_id?'universe-selected':''}" data-act="subset" data-index="${s.subset_id}" style="animation:fan-in .55s ${i*60}ms both"><div class="universe-row"><span class="universe-id"><span class="universe-status ${s.is_winner?'':'loss'}">${s.is_winner?'✓':'◉'}</span>Вариант ${String(s.subset_id).padStart(2,'0')}</span><span class="universe-total">${fmt(s.total_consistency_energy)}</span></div><div class="bar-back"><div class="energy-fill ${s.is_winner?'winning':''}" style="width:${pct}%;animation:energy-in 1.2s ease-out both"></div></div><div class="energy-meta"><span>Основа: ${fmt(s.base_v79_energy)}</span><span>Δ Joint: ${fmt(s.joint_v710_residual_energy)}</span></div>${s.conflict_detected?'<span class="danger-pill">! Диагностика конфликта</span>':''}${c.selectedSubset===s.subset_id?`<div class="universe-detail"><div class="detail-label">ЗАЯВЛЕННЫЕ ЭФФЕКТЫ</div>${s.effects_applied.length?s.effects_applied.map(t=>`<div class="effect-line">${enc(rusEffect(t))}</div>`).join(''):'<div class="effect-line">Изменения не выбраны</div>'}<div class="diag-inline">Недопустимый ресурс: ${s.diagnostics.invalid_numeric||0} · Противоположные записи: ${s.diagnostics.opposed_relations||0}</div></div>`:''}</button>`}).join('')}</div>${subsets.length>6?`<button class="show-more" data-act="show-all">${c.showAll?'Свернуть варианты':'Показать все '+subsets.length+' вариантов'} ▾</button>`:''}<div class="truth-foot">⚠ Конфликты помечены только после выбора. Ни одного фильтра при argmax.</div></div>`}
function timeline(c){return `<div class="history-panel"><div class="block-header"><div><span class="eyebrow">◷ ВРЕМЕННАЯ ШКАЛА</span><h3>История <span>мира</span></h3></div><span class="tag tag-neutral">${c.data.history.length} шагов</span></div><p class="history-intro">Каждый шаг хранит исходное состояние, действие, все оценённые варианты и результат.</p><div class="timeline"><button class="timeline-item ${c.selectedHistory===0?'chosen':''}" data-act="history" data-index="0"><span class="timeline-axis"></span><span class="timeline-number">◈</span><span class="timeline-text"><b>Начальный мир</b><small>Состояние до первого действия</small></span>›</button>${c.data.history.map(h=>`<button class="timeline-item ${c.selectedHistory===h.number?'chosen':''}" data-act="history" data-index="${h.number}"><span class="timeline-axis"></span><span class="timeline-number">${h.number}</span><span class="timeline-text"><b>${enc(h.action.verb)} · ${enc(name(h.action.target.replaceAll('_',' '),22))}</b><small>${enc(h.action.actor)} · вариант #${h.response.step_log.winner_subset_id}</small></span>›</button>`).join('')}</div>${c.selectedHistory!==null?`<div class="timeline-inspect"><span class="tag tag-amber">СНИМОК №${c.selectedHistory}</span><p>На карте — состояние из истории. Для продолжения из него создайте новую ветку.</p><button class="btn btn-accent" data-act="branch">⋈ Продолжить отсюда</button></div>`:''}</div>`}
function render(c,animate=false){
 const {world:shown,before,record}=current(c),hist=c.data.history;
 const oldFacts=new Set((before?.relations||shown.relations).map(r=>[r.predicate,r.source,r.target].join('/'))),newFacts=new Set(shown.relations.map(r=>[r.predicate,r.source,r.target].join('/')));
 const changes=shown.entities.filter(e=>before&&e.stock!==before.entities.find(x=>x.id===e.id)?.stock).length+[...oldFacts].filter(x=>!newFacts.has(x)).length+[...newFacts].filter(x=>!oldFacts.has(x)).length;
 const m=record?.response.step_log.evaluated_subsets.length||0;
 c.el.innerHTML=`<main class="twm-app"><header class="topbar"><div class="brand-symbol">⚛<span class="brand-spark"></span></div><div class="brand-text"><div class="brand-name">TWM <span>WORLD SANDBOX</span><b class="beta">BETA</b></div><div class="brand-caption">ЛАБОРАТОРИЯ НЕЙРОСИМВОЛЬНОЙ МОДЕЛИ МИРА</div></div><div class="topbar-center"><span class="tiny-label">СЦЕНАРИЙ</span><select data-field="preset">${c.data.presets.map((p,i)=>`<option value="${i}" ${c.data.presetIndex===i?'selected':''}>${enc(p.name)}</option>`).join('')}</select>⌄</div><div class="topbar-right"><span class="online"><span class="pulse-dot"></span>МОДЕЛЬ ЗАГРУЖЕНА</span><div class="top-separator"></div><span class="model-tag">v7.10 · Seed 801</span><div class="top-separator"></div><span class="step-pill">Шаг <strong>${String(hist.length).padStart(2,'0')}</strong></span><button class="btn btn-ghost" title="Сброс" data-act="reset">↺</button></div></header>
 <div class="workspace"><aside class="left-panel"><div class="panel-heading"><span class="eyebrow"><span class="section-mark"></span> ПАНЕЛЬ УПРАВЛЕНИЯ</span><h2>Конструктор <span>мира</span></h2><p>Редактируйте факты, ресурсы и законы. Модель сама выбирает последствия.</p></div><div class="left-scroll">${entityInspector(c)}${relationInspector(c)}${lawsInspector(c)}</div><div class="left-footer"><button class="btn" style="width:100%" data-act="download">↓ Экспортировать JSON эксперимента</button></div></aside>
 <section class="center-panel"><div class="center-head"><div class="center-breadcrumb"><span class="crumb-active">ПРОСТРАНСТВО МИРА</span> › <span>СИМУЛЯЦИЯ / SEED 801</span></div><div class="center-head-actions"><span class="status-text"><span></span> НЕЙРОННЫЙ ИНФЕРЕНС</span><span class="tag tag-neutral">CPU</span></div></div><div class="insight-strip">${[['⬡','СУЩНОСТЕЙ',shown.entities.length],['⋈','ОТНОШЕНИЙ',shown.relations.length],['ϟ','ОЦЕНЕНО ВАРИАНТОВ',m||'—'],['◉','ИЗМЕНЕНИЙ ЗА ШАГ',changes]].map(([ico,label,value],i)=>`<div class="insight"><div class="insight-icon ${i===2?'highlight':''}">${ico}</div><div><span>${label}</span><b>${value}</b></div></div>`).join('')}</div><div class="arena-container">${worldGraph(c,shown,before)}</div><div class="center-lower">${results(c,record)}</div>${c.data.error||c.error?`<div class="error-banner"><span>!</span><div><b>Действие не выполнено</b><p>${enc(c.error||c.data.error)}</p></div><button data-act="clear-error">×</button></div>`:''}${c.selectedHistory!==null?`<div class="preview-notice">◷ Просмотр снимка №${c.selectedHistory}. Рабочий мир не изменён. <button class="btn btn-accent" data-act="branch">Создать ветку</button><button class="btn" data-act="history-current">К текущему</button></div>`:''}${actionConsole(c)}</section>
 <aside class="right-panel"><div class="right-tabs"><button class="${c.tab==='multiverse'?'active':''}" data-act="tab" data-tab="multiverse">⋈ Варианты <span>${m}</span></button><button class="${c.tab==='history'?'active':''}" data-act="tab" data-tab="history">◷ История <span>${hist.length}</span></button></div><div class="right-scroll">${c.tab==='history'?timeline(c):multiverse(c,record)}</div><div class="right-footer"><div class="integrity-icon">◇</div><div><strong>Без программной посткоррекции</strong><span>Все оценки получены из сети. Эталон не выполняется при прогнозе.</span></div></div></aside></div><footer class="bottom-bar"><div><span class="tiny-blink"></span> TWM v7.10 · исследовательская грамматика · до 5 законов · до 8 эффектов</div><div>Визуальные типы объектов не равны входным нейронным признакам · протокол: argmax</div></footer></main>`;
 if(animate){const arena=c.el.querySelector('.arena');if(arena?.animate)arena.animate([{opacity:.65,filter:'brightness(1.25)'},{opacity:1,filter:'brightness(1)'}],{duration:850});}
}
function setupHandlers(c){
 c.el.addEventListener('click',event=>{
  const el=event.target.closest('[data-act]');if(!el||c.busy)return;const act=el.dataset.act,idx=Number(el.dataset.index),id=el.dataset.id;
  if(act==='entity'){c.selectedEntity=c.selectedEntity===id?null:id;}
  else if(act==='add-entity'){c.addEntity=!c.addEntity;}
  else if(act==='confirm-entity'){const name=c.newId.trim();if(name&&!c.world.entities.some(e=>e.id===name)&&c.world.entities.length<32){c.world.entities.push({id:name,kind:c.newKind,stock:2,capacity:10,properties:{}});c.addEntity=false;c.selectedEntity=name;}}
  else if(act==='del-entity'){if(c.world.entities.length>3){c.world.entities=c.world.entities.filter(e=>e.id!==id);c.world.relations=c.world.relations.filter(r=>r.source!==id&&r.target!==id);if(c.selectedEntity===id)c.selectedEntity=null;}}
  else if(act==='add-relation'){c.addRelation=!c.addRelation;c.newRelation={predicate:'подходит',source:c.world.entities[0]?.id||'',target:c.world.entities[1]?.id||''};}
  else if(act==='confirm-relation'){const r=c.newRelation;if(r.predicate.trim()&&!r.predicate.startsWith('__twm_action__/')&&!c.world.relations.some(x=>x.source===r.source&&x.target===r.target&&x.predicate===r.predicate)){c.world.relations.push(clone(r));c.addRelation=false;}}
  else if(act==='del-relation')c.world.relations.splice(idx,1);
  else if(act==='toggle-law')c.laws[idx].enabled=!c.laws[idx].enabled;
  else if(act==='edit-law'){c.editLaw=c.editLaw===idx?null:idx;c.conditionDraft=c.editLaw===null?'':JSON.stringify(c.laws[idx].condition,null,2);}
  else if(act==='move-law-up'||act==='move-law-down'){const j=idx+(act.endsWith('up')?-1:1);if(j>=0&&j<c.laws.length){[c.laws[idx],c.laws[j]]=[c.laws[j],c.laws[idx]];c.laws.forEach((l,i)=>l.priority=20-i)}}
  else if(act==='del-law'){if(c.laws.length>1){c.laws.splice(idx,1);c.editLaw=null;}}
  else if(act==='add-law'){if(c.laws.length<5){const n=c.laws.length+1;c.laws.push({...clone(c.laws[0]),id:'закон_'+n,priority:20-n,enabled:false});}}
  else if(act==='save-condition'){try{const r=JSON.parse(c.conditionDraft);if(!r||!('table'in r)&&!('predicate'in r))throw Error('Ожидается AST');c.laws[c.editLaw].condition=r;c.error=null;}catch(e){c.error='Некорректный JSON условия: '+e.message;}}
  else if(act==='subset')c.selectedSubset=c.selectedSubset===idx?null:idx;
  else if(act==='show-all')c.showAll=!c.showAll;
  else if(act==='history'){c.selectedHistory=c.selectedHistory===idx?null:idx;}
  else if(act==='history-current')c.selectedHistory=null;
  else if(act==='tab')c.tab=el.dataset.tab;
  else if(act==='clear-error')c.error=null;
  else if(act==='download'){const payload=JSON.stringify({world_state:c.world,laws:c.laws,action:c.action},null,2);const url=URL.createObjectURL(new Blob([payload],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='twm_eksperiment.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);return;}
  else if(act==='reset'){send(c,{type:'reset'});return;}
  else if(act==='branch'){send(c,{type:'branch',number:c.selectedHistory});return;}
  else if(act==='step'){
    const count=c.laws.filter(l=>l.enabled).length,ids=new Set(c.world.entities.map(e=>e.id));
    if(count<1||count>5)c.error='Для инференса требуется от 1 до 5 включённых законов.';
    else if(c.world.entities.some(e=>e.stock<0||e.stock>e.capacity||e.capacity<=0))c.error='Начальные ресурсы должны быть в пределах вместимости. Предсказанное моделью нарушение не исправляется.';
    else if(!ids.has(c.action.actor)||!ids.has(c.action.target)||(c.action.instrument&&!ids.has(c.action.instrument)))c.error='В действии есть ссылка на отсутствующую сущность.';
    else{c.error=null;send(c,{type:'step',request:{world_state:c.world,laws:c.laws,action:c.action}});return;}
  }
  render(c);
 });
 c.el.addEventListener('change',event=>{
  if(c.busy)return;const t=event.target,k=t.dataset.field;
  if(t.dataset.action){const fld=t.dataset.action;c.action[fld]=(fld==='instrument'?t.value||null:t.value);}
  else if(k==='preset'){send(c,{type:'preset',index:Number(t.value)});return;}
  else if(k==='stock'||k==='capacity'){const e=c.world.entities.find(x=>x.id===t.dataset.id);if(e)e[k]=Number(t.value);}
  else if(k==='new-id')c.newId=t.value;
  else if(k==='new-kind')c.newKind=t.value;
  else if(k==='rel-p')c.newRelation.predicate=t.value;
  else if(k==='rel-a')c.newRelation.source=t.value;
  else if(k==='rel-b')c.newRelation.target=t.value;
  else if(k==='condition')c.conditionDraft=t.value;
  else if(t.dataset.lawField){const law=c.laws[Number(t.dataset.law)],f=t.dataset.lawField;law[f]=f==='amount'?Number(t.value):f==='relation_add'?t.value==='true':t.value;}
  if(t.tagName==='INPUT'||t.tagName==='TEXTAREA')return; // не заменять DOM на blur перед нажатием кнопки
  render(c);
 });
 c.el.addEventListener('input',event=>{const t=event.target;if(t.dataset.field==='condition')c.conditionDraft=t.value; else if(t.dataset.action)c.action[t.dataset.action]=t.value;else if(t.dataset.field==='new-id')c.newId=t.value;else if(t.dataset.field==='rel-p')c.newRelation.predicate=t.value;else if(t.dataset.lawField)c.laws[Number(t.dataset.law)][t.dataset.lawField]=t.dataset.lawField==='amount'?Number(t.value):t.value;});
}
function send(c,msg){c.busy=true;render(c);c.trigger('command',JSON.stringify(msg));}
export default function(component){
 const el=component.parentElement.querySelector('#twm-sandbox-react-root');if(!el)return;
 let c=instances.get(el),newInstance=!c;
 if(!c){c={el,world:clone(component.data.world_state),laws:clone(component.data.laws),action:clone(component.data.action),data:component.data,revision:component.data.revision,selectedEntity:null,selectedSubset:null,selectedHistory:null,tab:'multiverse',addEntity:false,addRelation:false,editLaw:null,newId:'новый_объект',newKind:'object',newRelation:{predicate:'подходит',source:'',target:''},conditionDraft:'',showAll:false,busy:false,error:null,trigger:component.setTriggerValue};instances.set(el,c);setupHandlers(c);}
 c.trigger=component.setTriggerValue;c.data=component.data;
 let newResult=false;
 if(c.revision!==component.data.revision){c.revision=component.data.revision;c.world=clone(component.data.world_state);c.laws=clone(component.data.laws);c.action=clone(component.data.action);c.busy=false;c.selectedEntity=null;c.selectedSubset=null;c.selectedHistory=null;c.showAll=false;c.error=null;c.editLaw=null;newResult=Boolean(component.data.history.length);c.tab=newResult?'multiverse':c.tab;}
 render(c,newResult);
}
